     1|// EqCanvas.h — EQ compacto con las 124 bandas visibles a la vez, arrastre con
     2|// el ratón, colores por ecu dinámico que trabaja en cada banda y marcador de
     3|// la banda activa. Port del CompactEqCanvas + DynamicEqColors de la app móvil.
     4|#pragma once
     5|
     6|#include <juce_gui_basics/juce_gui_basics.h>
     7|#include <AcousticalEngine.h>
     8|#include "Theme.h"
     9|
    10|class EqCanvas : public juce::Component {
    11|public:
    12|    struct Snapshot {
    13|        std::vector<float> gains;                    // ganancia combinada por banda
    14|        std::vector<float> bandFrequencies;
    15|        std::map<int, juce::Colour> highlights;      // banda → color del ecu que la trabaja
    16|        int activeBand = -1;
    17|        juce::Colour activeColour = theme::eq1Cyan;
    18|        float maxGainDb = 12.0f;
    19|        bool stereoUnlinked = false;
    20|        std::vector<float> gainsR;
    21|    };
    22|
    23|    explicit EqCanvas(std::function<void(int, float)> onBandChanged)
    24|        : onBandChanged_(std::move(onBandChanged)) {
    25|        setMouseClickGrabsKeyboardFocus(false);
    26|        setBufferedToImage(true);
    27|    }
    28|
    29|    void setSnapshot(const Snapshot& s) {
    30|        std::lock_guard<std::mutex> lock(mutex_);
    31|        snapshot_ = s;
    32|        repaint();
    33|    }
    34|
    35|    void paint(juce::Graphics& g) override {
    36|        Snapshot snap;
    37|        {
    38|            std::lock_guard<std::mutex> lock(mutex_);
    39|            snap = snapshot_;
    40|        }
    41|        const auto bounds = getLocalBounds().toFloat().reduced(8.0f);
    42|        const int n = static_cast<int>(snap.bandFrequencies.size());
    43|        if (n == 0) {
    44|            g.setColour(theme::textDim);
    45|            g.drawText("Arranca el motor para ver las bandas", getLocalBounds(),
    46|                       juce::Justification::centred);
    47|            return;
    48|        }
    49|
    50|        const float w = bounds.getWidth() / static_cast<float>(n);
    51|        const float zeroY = bounds.getCentreY();
    52|        const float half = bounds.getHeight() / 2.0f - 6.0f;
    53|        const float maxG = std::max(snap.maxGainDb, 1.0f);
    54|
    55|        // Línea de 0 dB y marcas 100 / 1k / 10k
    56|        g.setColour(theme::surfaceHi);
    57|        g.fillRect(bounds.getX(), zeroY - 0.5f, bounds.getWidth(), 1.0f);
    58|        g.setColour(theme::textDim);
    59|        g.setFont(10.0f);
    60|        for (float mark : {100.0f, 1000.0f, 10000.0f}) {
    61|            int nearest = 0;
    62|            float best = 1e9f;
    63|            for (int i = 0; i < n; ++i) {
    64|                const float d = std::abs(std::log10(snap.bandFrequencies[i] / mark));
    65|                if (d < best) { best = d; nearest = i; }
    66|            }
    67|            const float x = bounds.getX() + (nearest + 0.5f) * w;
    68|            g.setColour(theme::surfaceHi);
    69|            g.fillRect(x, bounds.getY(), 1.0f, bounds.getHeight());
    70|            g.setColour(theme::textDim);
    71|            g.drawText(mark >= 1000.0f ? juce::String(mark / 1000.0f, 0) + "k"
    72|                                       : juce::String(mark, 0),
    73|                       juce::Rectangle<float>(x - 12.0f, bounds.getBottom() - 14.0f, 24.0f, 12.0f),
    74|                       juce::Justification::centred);
    75|        }
    76|
    77|        // Faders finos, tintados con el color del ecu dinámico que los trabaja
    78|        for (int i = 0; i < n; ++i) {
    79|            const float gain = i < static_cast<int>(snap.gains.size()) ? snap.gains[i] : 0.0f;
    80|            const float x = bounds.getX() + i * w;
    81|            const float barW = std::max(w - std::max(w * 0.25f, 0.6f), 1.2f);
    82|
    83|            auto colour = theme::primaryDark;
    84|            const auto it = snap.highlights.find(i);
    85|            if (it != snap.highlights.end()) colour = it->second;
    86|            if (i == snap.activeBand) colour = juce::Colours::white;
    87|
    88|            if (gain >= 0.0f) {
    89|                const float h = (gain / maxG) * half;
    90|                g.setColour(colour.withAlpha(0.9f));
    91|                g.fillRoundedRectangle(x + w * 0.1f, zeroY - h, barW, std::max(h, 1.0f), 1.5f);
    92|            } else {
    93|                const float h = (-gain / maxG) * half;
    94|                g.setColour(colour.withAlpha(0.65f));
    95|                g.fillRoundedRectangle(x + w * 0.1f, zeroY, barW, std::max(h, 1.0f), 1.5f);
    96|            }
    97|
    98|            // Marcador circular en la cima de la banda activa
    99|            if (i == snap.activeBand) {
   100|                const float y = zeroY - (gain >= 0.0f ? (gain / maxG) * half
   101|                                                      : -(-gain / maxG) * half);
   102|                g.setColour(snap.activeColour);
   103|                g.fillEllipse(x + w / 2.0f - 3.0f, y - 3.0f, 6.0f, 6.0f);
   104|            }
   105|        }
   106|    }
   107|
   108|    void mouseDrag(const juce::MouseEvent& e) override {
   109|        Snapshot snap;
   110|        {
   111|            std::lock_guard<std::mutex> lock(mutex_);
   112|            snap = snapshot_;
   113|        }
   114|        const int n = static_cast<int>(snap.bandFrequencies.size());
   115|        if (n == 0) return;
   116|        const auto bounds = getLocalBounds().toFloat().reduced(8.0f);
   117|        const float w = bounds.getWidth() / static_cast<float>(n);
   118|        const int index = juce::jlimit(0, n - 1,
   119|            static_cast<int>((e.position.x - bounds.getX()) / w));
   120|        const float zeroY = bounds.getCentreY();
   121|        const float half = bounds.getHeight() / 2.0f - 6.0f;
   122|        const float gain = juce::jlimit(-snap.maxGainDb, snap.maxGainDb,
   123|                                        -(e.position.y - zeroY) / half * snap.maxGainDb);
   124|        if (onBandChanged_) onBandChanged_(index, gain);
   125|    }
   126|
   127|    void mouseDown(const juce::MouseEvent& e) override { mouseDrag(e); }
   128|
   129|    void mouseUp(const juce::MouseEvent& e) override {
   130|        juce::ignoreUnused(e);
   131|        // Etiqueta exacta de la banda bajo el ratón (como en el móvil)
   132|    }
   133|
   134|private:
   135|    std::function<void(int, float)> onBandChanged_;
   136|    Snapshot snapshot_;
   137|    std::mutex mutex_;
   138|};

