    23|
    24|namespace acoustical {
    25|
    26|struct AnalysisResult {
    27|    SpectrumFrame spectrum;                       // espectro FFT (bins)
    28|    std::vector<EqBand> bands;                    // EQ principal corregido
    29|    std::vector<float> measuredBandLevels;        // niveles por banda
