   142|
   143|    // === Atajos de teclado ===
   144|    bool keyPressed(const juce::KeyPress& key) override {
   145|        if (key == juce::KeyPress::F1Key) { toggleDynamicEq(0); return true; }
   146|        if (key == juce::KeyPress::F2Key) { toggleDynamicEq(1); return true; }
   147|        if (key == juce::KeyPress::F3Key) { toggleDynamicEq(2); return true; }
   148|        if (key == juce::KeyPress::spaceKey) { freezeButton_.triggerClick(); return true; }
