   159|private:
   160|    // === Motor / audio ===
   161|
   162|    void toggleEngine() {
   163|        if (engine_.isRunning()) {
   164|            engine_.stop();
   165|            powerButton_.setButtonText("Motor");
   166|        } else {
   167|            engine_.start();
   168|            powerButton_.setButtonText("Parar");
   169|        }
   170|    }
   171|
   172|    void toggleDynamicEq(int index) {
   173|        const bool target = !dynamicEqEnabled_[index];
   174|        engine_.setDynamicEqEnabled(index, target);
   175|        dynamicEqEnabled_[index] = target;
   176|    }
   177|
   178|    void toggleFullscreen() {
   179|        if (auto* w = findParentComponentOfClass<juce::DocumentWindow>()) {
   180|            const bool target = !w->isFullScreen();
   181|            w->setFullScreen(target);
   182|            fullscreenButton_.setToggleState(target, juce::dontSendNotification);
   183|        }
   184|    }
   185|
   186|    void audioDeviceIOCallbackWithContext(const float* const* input, int numInputs,
   187|                                          float* const* output, int numOutputs,
   188|                                          int numSamples,
   189|                                          const juce::AudioIODeviceCallbackContext&) override {
   190|        std::vector<float> mono(static_cast<size_t>(numSamples), 0.0f);
   191|        for (int ch = 0; ch < numInputs; ++ch)
   192|            if (const auto* in = input[ch])
   193|                for (int s = 0; s < numSamples; ++s) mono[s] += in[s];
   194|
   195|        // Generador de señales → se procesa por el EQ como una entrada más
   196|        if (generatorActive_.load() && numOutputs > 0) {
   197|            generatorBuffer_.assign(static_cast<size_t>(numSamples), 0.0f);
   198|            engine_.signalGenerator().fill(generatorBuffer_.data(), numSamples,
   199|                                           static_cast<float>(lastSampleRate_));
   200|            for (int s = 0; s < numSamples; ++s) mono[s] += generatorBuffer_[s];
   201|        }
   202|
   203|        engine_.pushSamples(mono.data(), numSamples, lastSampleRate_);
   204|
   205|        // Salida: EQ en tiempo real por canal (correcciones de los 3 ecuas)
   206|        std::vector<float> left(static_cast<size_t>(numSamples));
   207|        std::vector<float> right(static_cast<size_t>(numSamples));
   208|        {
   209|            std::lock_guard<std::mutex> lock(dspMutex_);
   210|            std::copy(mono.begin(), mono.end(), left.begin());
   211|            std::copy(mono.begin(), mono.end(), right.begin());
   212|            engine_.eqDspL().process(left.data(), numSamples);
   213|            engine_.eqDspR().process(right.data(), numSamples);
   214|        }
   215|
   216|        if (numOutputs > 0 && output[0])
   217|            std::copy(left.begin(), left.end(), output[0]);
   218|        if (numOutputs > 1 && output[1])
   219|            std::copy(right.begin(), right.end(), output[1]);
   220|        for (int ch = 2; ch < numOutputs; ++ch)
   221|            if (output[ch])
   222|                std::copy(right.begin(), right.end(), output[ch]);
   223|    }
   224|
   225|    void audioDeviceAboutToStart(juce::AudioIODevice* device) override {
   226|        lastSampleRate_ = device ? device->getCurrentSampleRate() : 48000.0;
   227|    }
