   245|    void timerCallback() override {
   246|        // 1. EQ principal con resaltados por ecu dinámico
   247|        EqCanvas::Snapshot snap;
   248|        {
   249|            std::lock_guard<std::mutex> lock(analysisMutex_);
   250|            if (!lastAnalysis_) return;
   251|            snap.bandFrequencies = engine_.bandFrequencies();
   252|            snap.gains = lastAnalysis_->combinedGainsL;
   253|            snap.gainsR = lastAnalysis_->combinedGainsR;
